package com.xyz.question_bank_management_system.modules.profile.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper; import com.xyz.question_bank_management_system.exception.*; import com.xyz.question_bank_management_system.modules.competency.entity.Skill; import com.xyz.question_bank_management_system.modules.competency.mapper.SkillMapper; import com.xyz.question_bank_management_system.modules.profile.entity.*; import com.xyz.question_bank_management_system.modules.profile.mapper.*; import com.xyz.question_bank_management_system.modules.profile.service.ResumeEvidenceService; import com.xyz.question_bank_management_system.modules.source.entity.FileAsset; import com.xyz.question_bank_management_system.modules.source.mapper.FileAssetMapper; import com.xyz.question_bank_management_system.util.HashUtil; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.time.LocalDateTime; import java.util.*;
@Service @RequiredArgsConstructor public class ResumeEvidenceServiceImpl implements ResumeEvidenceService {
 private final StudentResumeMapper mapper; private final SkillMapper skillMapper; private final FileAssetMapper assetMapper; private final StudentEvidenceMapper evidenceMapper; private final ObjectMapper objectMapper; @Value("${app.file.storage-dir:uploads}") private String storageDir;
 @Override @Transactional public StudentResumeDocument upload(MultipartFile file,String consentVersion,Long userId){try{if(file==null||file.isEmpty())throw BizException.of(ErrorCode.PARAM_ERROR,"resume file is required");String text=new String(file.getBytes(),StandardCharsets.UTF_8);String hash=HashUtil.sha256(text);StudentResumeDocument old=mapper.byHash(userId,hash);if(old!=null)return old;Path dir=Paths.get(storageDir).toAbsolutePath().normalize().resolve("student-resumes");Files.createDirectories(dir);Path target=dir.resolve(hash+".txt");Files.write(target,file.getBytes(),StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);FileAsset asset=new FileAsset();asset.setBizType("student_resume");asset.setFileName(Objects.toString(file.getOriginalFilename(),"resume.txt"));asset.setFileExt("txt");asset.setMimeType(file.getContentType());asset.setStorageType("local");asset.setStoragePath(target.toString());asset.setFileSize(file.getSize());asset.setFileHash(hash);asset.setUploadedBy(userId);assetMapper.insert(asset);StudentResumeDocument doc=new StudentResumeDocument();doc.setUserId(userId);doc.setFileAssetId(asset.getId());doc.setFileName(asset.getFileName());doc.setFileHash(hash);doc.setParsedText(text);doc.setParseStatus("PARSED");doc.setParserVersion("resume_text_match_v1");doc.setConsentVersion(consentVersion);mapper.insertDocument(doc);asset.setBizId(doc.getId());assetMapper.updateBizId(asset);extract(doc,text);return doc;}catch(BizException e){throw e;}catch(Exception e){throw BizException.of(ErrorCode.BIZ_ERROR,"resume upload failed: "+e.getMessage());}}
 private void extract(StudentResumeDocument doc,String text){for(Skill skill:skillMapper.selectPage(null,0,1000)){String name=skill.getNameZh();if(name==null||name.isBlank()||!text.toLowerCase(Locale.ROOT).contains(name.toLowerCase(Locale.ROOT)))continue;StudentResumeEvidence ev=new StudentResumeEvidence();ev.setResumeId(doc.getId());ev.setTargetType("SKILL");ev.setTargetId(skill.getId());ev.setRawName(name);ev.setNormalizedName(name);ev.setEvidenceValue(BigDecimal.ONE);ev.setConfidence(new BigDecimal("0.3500"));ev.setEvidenceText(sentence(text,name));ev.setMatchStatus("MATCHED");ev.setModelVersion("resume_text_match_v1");ev.setSourceSpanJson(json(Map.of("matchedText",name)));ev.setAppliedStatus("CANDIDATE");mapper.upsertEvidence(ev);}}
 @Override public List<StudentResumeDocument> documents(Long userId){return mapper.documents(userId);} @Override public List<StudentResumeEvidence> evidence(Long resumeId,Long userId){if(mapper.document(resumeId,userId)==null)throw BizException.of(ErrorCode.NOT_FOUND,"resume not found");return mapper.evidence(resumeId);} @Override @Transactional public void confirm(Long resumeId,Long evidenceId,boolean accepted,Long userId){if(mapper.document(resumeId,userId)==null)throw BizException.of(ErrorCode.NOT_FOUND,"resume not found");List<StudentResumeEvidence> all=mapper.evidence(resumeId);StudentResumeEvidence ev=all.stream().filter(x->Objects.equals(x.getId(),evidenceId)).findFirst().orElseThrow(()->BizException.of(ErrorCode.NOT_FOUND,"evidence not found"));String status=accepted?"CONFIRMED":"REJECTED";mapper.confirm(evidenceId,resumeId,status);if(accepted){StudentEvidence unified=new StudentEvidence();unified.setUserId(userId);unified.setEvidenceType("RESUME_CANDIDATE");unified.setSourceEntityType("RESUME");unified.setSourceEntityId(resumeId);unified.setTargetType("SKILL");unified.setTargetId(ev.getTargetId());unified.setEvidenceValue(ev.getEvidenceValue());unified.setEvidenceDirection(0);unified.setConfidence(ev.getConfidence());unified.setEvidenceText(ev.getEvidenceText());unified.setOccurredAt(LocalDateTime.now());unified.setExtractVersion("resume_text_match_v1");evidenceMapper.insertIgnore(unified);}}
 private String sentence(String text,String key){int i=text.toLowerCase(Locale.ROOT).indexOf(key.toLowerCase(Locale.ROOT));int s=Math.max(0,Math.max(text.lastIndexOf('\n',i),text.lastIndexOf('。',i))+1);int e=text.indexOf('\n',i);if(e<0)e=text.indexOf('。',i);return text.substring(s,e<0?Math.min(text.length(),i+200):e).trim();}private String json(Object v){try{return objectMapper.writeValueAsString(v);}catch(Exception e){return "{}";}}
}
